# backend/app/zones/router.py
import uuid

from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy.ext.asyncio import AsyncSession

from app.auth.deps import require_manager
from app.auth.models import User
from app.db import get_db
from app.zones.schemas import (
    ZoneAssignmentCreate,
    ZoneAssignmentOut,
    ZoneCreate,
    ZoneOut,
)
from app.zones.service import (
    AssignmentExistsError,
    RepNotFoundError,
    ZoneNotFoundError,
    assign_rep_to_zone,
    create_zone,
    get_zone,
    list_zones,
)

router = APIRouter(prefix="/api/v1/zones", tags=["zones"])


@router.post("", response_model=ZoneOut, status_code=status.HTTP_201_CREATED)
async def create_zone_endpoint(
    body: ZoneCreate,
    current_user: User = Depends(require_manager),
    db: AsyncSession = Depends(get_db),
) -> ZoneOut:
    zone = await create_zone(
        db, tenant_id=current_user.tenant_id, name=body.name, boundary=body.boundary.model_dump()
    )
    return zone


@router.get("", response_model=list[ZoneOut])
async def list_zones_endpoint(
    current_user: User = Depends(require_manager),
    db: AsyncSession = Depends(get_db),
) -> list[ZoneOut]:
    return await list_zones(db)


@router.get("/{zone_id}", response_model=ZoneOut)
async def get_zone_endpoint(
    zone_id: uuid.UUID,
    current_user: User = Depends(require_manager),
    db: AsyncSession = Depends(get_db),
) -> ZoneOut:
    zone = await get_zone(db, zone_id)
    if zone is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="zone not found")
    return zone


@router.post("/{zone_id}/assignments", response_model=ZoneAssignmentOut, status_code=status.HTTP_201_CREATED)
async def assign_rep_to_zone_endpoint(
    zone_id: uuid.UUID,
    body: ZoneAssignmentCreate,
    current_user: User = Depends(require_manager),
    db: AsyncSession = Depends(get_db),
) -> ZoneAssignmentOut:
    try:
        return await assign_rep_to_zone(
            db, tenant_id=current_user.tenant_id, zone_id=zone_id, rep_id=body.rep_id
        )
    except ZoneNotFoundError as exc:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="zone not found") from exc
    except RepNotFoundError as exc:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="rep not found") from exc
    except AssignmentExistsError as exc:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT, detail="rep already assigned to this zone"
        ) from exc

import contextvars
import uuid

from sqlalchemy import event
from sqlalchemy.orm import Mapped, Session, mapped_column, with_loader_criteria

current_tenant_id: contextvars.ContextVar[uuid.UUID | None] = contextvars.ContextVar(
    "current_tenant_id", default=None
)


class TenantScopedMixin:
    tenant_id: Mapped[uuid.UUID] = mapped_column(nullable=False, index=True)


_installed = False


def install_tenancy_filter() -> None:
    """Registers a global SELECT/UPDATE/DELETE filter scoping every TenantScopedMixin query
    to current_tenant_id. Idempotent — safe to call more than once (e.g. once
    per test)."""
    global _installed
    if _installed:
        return

    @event.listens_for(Session, "do_orm_execute")
    def _apply_tenant_filter(execute_state):
        # Apply tenant filter to SELECT, UPDATE, and DELETE statements
        if not (execute_state.is_select or execute_state.is_update or execute_state.is_delete):
            return
        tenant_id = current_tenant_id.get()
        if tenant_id is None:
            return
        execute_state.statement = execute_state.statement.options(
            with_loader_criteria(
                TenantScopedMixin,
                lambda cls: cls.tenant_id == tenant_id,
                include_aliases=True,
            )
        )

    _installed = True

